mapper.update:
UPDATE billing_wallet
SET frozen_balance_cny = frozen_balance_cny - #{reserved},
    available_balance_cny = available_balance_cny + #{refund} - #{overage},
    total_consumed_cny = total_consumed_cny + #{actual},
    version = version + 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND frozen_balance_cny >= #{reserved}
  AND available_balance_cny + #{refund} >= #{overage}
